// Общие шаги для тестов «WhatsApp למוכר» (#1d8184, #1d84d2, #e8bbad).
// Прод, только чтение: кнопки WhatsApp НЕ нажимаются (клик пишет лид продавцу) — читается href ссылок wa.me.
import { expect, BrowserContext, Page } from '@playwright/test';

export const WWW = 'https://www.biz4sale.co.il';
export const VERCEL = 'https://biz4sale.vercel.app';
/** Загрузка выдачи/объявления на проде под параллельной нагрузкой бывает 10+ с. */
export const LOAD = { timeout: 25_000 };

/** Известные объявления (только чтение): код /b/ → полный id. */
export const LISTINGS: Record<string, string> = {
  bd5c4929: 'bd5c4929-dad3-4b75-bfb2-eae74e69f664',
  '4d62fda8': '4d62fda8-629a-4ad5-9913-3f925cbbb1d1',
  '7d6e4de2': '7d6e4de2-0f49-43fb-8e80-38b7c314a61e',
  '23c080df': '23c080df-7b0e-452d-9861-5f6a90f745f9',
  '5832e079': '5832e079-87c7-49a8-9c24-97e7664dcba6',
};

/** Ссылки WhatsApp продавцу в карточках (текст содержит «BIZ4SALE»; «שירות הלקוחות» и т.п. отсеиваются ниже). */
export const SELLER_WA = 'a[href*="wa.me"][href*="BIZ4SALE"]';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];

/**
 * Вызывать до первого перехода. На уровне контекста (видит и запросы service worker в Chromium):
 * - не-GET/HEAD/OPTIONS обрываются (просмотры, user_activity, inquiry — на проде ничего не пишем);
 * - переходы на wa.me / whatsapp.com обрываются;
 * - баннер cookie заранее закрыт «только необходимые».
 */
export async function prepareReadOnly(context: BrowserContext) {
  await context.route('**/*', (route) => {
    const req = route.request();
    if (/^https?:\/\/(wa\.me|[^/]*whatsapp\.com)\//.test(req.url())) return route.abort('blockedbyclient');
    return SAFE_METHODS.includes(req.method()) ? route.fallback() : route.abort('blockedbyclient');
  });
  await context.addInitScript(() => {
    try {
      if (!localStorage.getItem('cookie-consent-v2')) {
        localStorage.setItem(
          'cookie-consent-v2',
          JSON.stringify({ essential: true, performance: false, marketing: false, updatedAt: new Date().toISOString() }),
        );
      }
    } catch {}
  });
}

export type SellerMessage = { cardId: string | null; text: string };

/** Раскодировать text= всех ссылок WhatsApp продавцу на странице + id карточки (ближайшая ссылка /businessdetail?id=). */
export async function readSellerMessages(page: Page): Promise<SellerMessage[]> {
  await expect(page.locator(SELLER_WA).first(), 'в карточках есть ссылки WhatsApp продавцу').toBeAttached(LOAD);
  return page.evaluate((sel) => {
    const res: { cardId: string | null; text: string }[] = [];
    for (const a of Array.from(document.querySelectorAll<HTMLAnchorElement>(sel))) {
      const text = new URL(a.href).searchParams.get('text') || '';
      if (!text.includes('BIZ4SALE ואני')) continue;
      let el: Element | null = a;
      let cardId: string | null = null;
      for (let i = 0; i < 12 && el && !cardId; i++) {
        el = el.parentElement;
        const l = el?.querySelector<HTMLAnchorElement>('a[href*="businessdetail?id="]');
        if (l) cardId = new URL(l.href).searchParams.get('id');
      }
      res.push({ cardId, text });
    }
    return res;
  }, SELLER_WA);
}

const GREETING = 'שלום, הגעתי דרך אתר BIZ4SALE ואני מתעניין במודעה שלך לגבי העסק "';
const CTA_LINE = 'לצפייה במודעה';

/** Проверка формата одного сообщения: приветствие / «לצפייה במודעה» без эмодзи / короткая ссылка www на эту карточку. */
export function expectSellerMessage(m: SellerMessage, where: string) {
  const lines = m.text.split('\n');
  const ctx = `${where}, карточка ${m.cardId}: ${JSON.stringify(m.text)}`;
  expect(lines, `3 строки: приветствие, «${CTA_LINE}», ссылка — ${ctx}`).toHaveLength(3);
  expect(lines[0].startsWith(GREETING), `приветствие с названием бизнеса — ${ctx}`).toBe(true);
  // #e8bbad: ровно «לצפייה במודעה» — без 👇, U+FFFD, U+FE0F, ZWJ и прочих символов.
  expect(lines[1], `строка перед ссылкой без эмодзи/битых символов — ${ctx}`).toBe(CTA_LINE);
  expect(m.cardId, `найден id карточки — ${ctx}`).toMatch(/^[0-9a-f]{8}-/);
  // #1d8184 + #1d84d2: короткая ссылка без GUID, всегда на www.biz4sale.co.il, код = первые 8 символов id карточки.
  expect(lines[2], `короткая ссылка www на эту карточку — ${ctx}`).toBe(`${WWW}/b/${m.cardId!.slice(0, 8)}`);
}

/** Дождаться, что service worker сайта установлен и управляет страницей. */
export async function waitServiceWorker(page: Page) {
  await page.waitForFunction(() => !!navigator.serviceWorker?.controller, null, { timeout: 30_000 });
}
